/** Virtual modules generated by scripts/build-mobile.mjs for the phone build. */

declare module "lh:routes" {
	export type RouteEntry = {
		/** Next-style path, e.g. "/api/chats/[id]". */
		path: string;
		/** Lazily imports the route module (app/api/.../route.ts). */
		load: () => Promise<Record<string, unknown>>;
	};
	export const routes: RouteEntry[];
}

declare module "lh:assets" {
	/** Read-only app files (agent prompts) keyed by virtual absolute path. */
	export const assets: Record<string, string>;
}
